public class PasswordForgeTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        try {
            check("generate(12, seed 1)", "zgi7UerOsj7A", PasswordForge.generate(12, 1L));
            check("generate(20, seed 5)", "fpT6QA47PNiuapf6hXsW", PasswordForge.generate(20, 5L));
            check("generate(3, seed 9) is the shortest legal length", "n8A", PasswordForge.generate(3, 9L));
            check("the same seed regenerates the same password",
                    PasswordForge.generate(16, 77L), PasswordForge.generate(16, 77L));

            check("satisfiesRule(\"Abcdefg1\")", true, PasswordForge.satisfiesRule("Abcdefg1"));
            check("satisfiesRule(\"Abcdef1\") is too short", false, PasswordForge.satisfiesRule("Abcdef1"));

            boolean all = true;
            for (long seed = 0; seed < 200; seed++) {
                if (!PasswordForge.satisfiesRule(PasswordForge.generate(10, seed))) {
                    all = false;
                }
            }
            check("every generated 10-character password satisfies the rule", true, all);
        } catch (RuntimeException e) {
            System.out.println("FAIL  unexpected exception -- expected none but got " + e);
            failures++;
        }

        String thrown = "no exception";
        try {
            PasswordForge.generate(2, 1L);
        } catch (IllegalArgumentException e) {
            thrown = "IllegalArgumentException";
        } catch (RuntimeException e) {
            thrown = e.getClass().getSimpleName();
        }
        check("generate(2, ...) rejects a too-short length", "IllegalArgumentException", thrown);

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

