/**
 * Generates reproducible passwords that always meet a character-class rule.
 */
public class PasswordForge {

    private static final String LOWER = "abcdefghijklmnopqrstuvwxyz";
    private static final String UPPER = "ABCDEFGHIJKLMNOPQRSTUVWXYZ";
    private static final String DIGITS = "0123456789";
    private static final String POOL = LOWER + UPPER + DIGITS;

    public static String generate(int length, long seed) {
        if (length < 3) {
            throw new IllegalArgumentException("length must be at least 3");
        }
        java.util.Random rng = new java.util.Random(seed);
        char[] out = new char[length];
        out[0] = LOWER.charAt(rng.nextInt(26));
        out[1] = UPPER.charAt(rng.nextInt(26));
        out[2] = DIGITS.charAt(rng.nextInt(10));
        for (int i = 3; i < length; i++) {
            out[i] = POOL.charAt(rng.nextInt(62));
        }
        for (int i = length - 1; i > 0; i--) {
            int j = rng.nextInt(i + 1);
            char tmp = out[i];
            out[i] = out[j];
            out[j] = tmp;
        }
        return new String(out);
    }

    public static boolean satisfiesRule(String password) {
        if (password == null || password.length() < 8) {
            return false;
        }
        boolean hasLower = false;
        boolean hasUpper = false;
        boolean hasDigit = false;
        for (int i = 0; i < password.length(); i++) {
            char c = password.charAt(i);
            if (c >= 'a' && c <= 'z') {
                hasLower = true;
            } else if (c >= 'A' && c <= 'Z') {
                hasUpper = true;
            } else if (c >= '0' && c <= '9') {
                hasDigit = true;
            }
        }
        return hasLower && hasUpper && hasDigit;
    }
}
